import React, {Component} from 'react';
import { Card, Button, Col } from 'react-bootstrap';

class Carteira extends Component {
    
    state = {
        digimons: [
            {
            
            }
        ]
    }
        async componentDidMount(){
            const digimons_Binance = await api.get('digimon');

            this.setState({
                digimons: digimons_Binance.data
            })
        }

    render () {
        return (
        <>
            {this.state.digimons.map( digimon =>
            <Col sm={3}>
                <Card style={{ width: '18rem' }}>
                    <Card.Img variant="top" src={digimon.value} />
                    <Card.Body>
                        <Card.Title>Nome: {digimon.name}</Card.Title>
                        <Card.Text>
                        Level: {digimon.level}
                        </Card.Text>
                        <Button variant="primary">Ver Digimon</Button>
                    </Card.Body>
                </Card>
            </Col>
            )}
        </>
        )
    }
}

export default Carteira;
